() => {
      const o = S.orders.filter((x: any) => x.id === id)[0];
      if (!o) {toast(cmsText("lbl.sheetOrderNotFound", "Order not found")); return;}
      if (!n) {toast(cmsText("lbl.sheetPickRating", "Pick a star rating")); return;}
      if (driver) {
        S.driverRev = S.driverRev || {};
        S.driverRev[id] = {n: S.pf.n, r: n, t: t.trim(), d: 'Just now', orderId: id};
        o.driverRated = n;
        o.driverReview = {r: n, t: t.trim(), d: 'Just now'};
      } else {
        S.rev[o.sid] = S.rev[o.sid] || [];
        S.rev[o.sid].unshift({n: S.pf.n, r: n, t: t.trim(), d: 'Just now', you: 1, orderId: id});
        o.rated = n;
        o.orderReview = {r: n, t: t.trim(), d: 'Just now'};
      }
      S.rt = 0; ui.close(); toast(driver ? cmsText("lbl.sheetDriverReviewThanks", "Thanks for rating your driver!") : cmsText("lbl.sheetReviewThanks", "Thanks for your review!")); save(); emit();
